import pathlib,os,errno,json,sys; p=pathlib.Path(sys.argv[1]); observed=None; written=0
try:
 with p.open("xb",buffering=0) as f:
  for n in range(12): written+=f.write(b"Q"*1048576); os.fsync(f.fileno())
except OSError as e: observed=e.errno
print(json.dumps({"uid":os.getuid(),"errno":observed,"errno_name":errno.errorcode.get(observed),"written_bytes":written})); sys.exit(0 if observed==errno.EDQUOT else 1)
